package mcp

// The tools/list entries of the mail tools, as src/mcp.ts's JSON.stringify writes them (generated by testdata/genlistings.mjs; mcp_test.go compares).
var mailListings = map[string]string{
	"read_mail":    "{\"name\":\"read_mail\",\"group\":\"mail\",\"description\":\"Read mail and mark it read. Without ids, reads up to 10: mail whose earlier read got no reply first (not FYI or system mail, nor mail over 6 hours old), then unread mail, oldest first.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ids\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}}}}",
	"list_inbox":   "{\"name\":\"list_inbox\",\"group\":\"mail\",\"description\":\"List your mail, newest first, without bodies.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"unread_only\":{\"type\":\"boolean\"},\"limit\":{\"type\":\"number\"}}}}",
	"read_thread":  "{\"name\":\"read_thread\",\"group\":\"mail\",\"description\":\"Read a mail thread you take part in, oldest first: the messages you sent or received in it. Also a thread with your user that one of your parents took part in, found with search_mail, and the threads of an ITSA you own or take part in, or whose parent ITSA you own. thread_id may be any mail id in the thread, such as one cited in your brief. Doesn't mark anything read.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"thread_id\":{\"type\":\"string\"}},\"required\":[\"thread_id\"]}}",
	"send_mail":    "{\"name\":\"send_mail\",\"group\":\"mail\",\"description\":\"Send mail to one or more agents by id or name, to \\\"all\\\", or to \\\"human\\\" (your user). Mail works like Slack threads: an answer to a mail joins its thread. Pass the mail's id as reply_to to be sure; without it, an answer to mail you just read joins that thread anyway (if you read several threads in the last 30 minutes and don't name one, the daemon errors listing them, so pass reply_to). For a new topic, pass new_thread: true. A reply reaches your user only when `to` names \\\"human\\\", in their own threads too. Bodies render as Markdown. Before mailing \\\"human\\\", search for the relevant thread with search_mail and read it: if one exists, reply in it with reply_to; if unsure, ask your parent. A new thread is fine when none fits, but continuing an existing one is preferred. Mail to \\\"human\\\" is only for what your user must decide or read (see your instructions); mail between agents has no such rules. The body holds about 5,000 tokens; longer text becomes an attachment. Attach files by path or inline content.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"to\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"subject\":{\"type\":\"string\",\"description\":\"Required for a new thread; optional with reply_to.\"},\"body\":{\"type\":\"string\"},\"reply_to\":{\"type\":\"string\",\"description\":\"Id of the mail this answers.\"},\"supersedes\":{\"type\":\"string\",\"description\":\"The exact id of an earlier mail of yours that this one replaces, after you find it was wrong. The old mail stays in its thread, but leaves inboxes, unread counts and notifications, and its ask to your user is withdrawn. Only your own mail, by exact id.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA (key such as S-12, or id) this mail is about: the web UI shows it as a chip in the mail header. Mail in an ITSA's own thread is about that ITSA already.\"},\"new_thread\":{\"type\":\"boolean\",\"description\":\"Start a new thread. Without it, an answer to a mail you just read joins that mail's thread.\"},\"override\":{\"type\":\"string\",\"description\":\"Only for mail to \\\"human\\\": a mail check refuses a mail your user doesn't need or that breaks the rules for mail to them. If you disagree, resend with the reason here; the mail goes out and your user sees the reason.\"},\"attachments\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"},\"content\":{\"type\":\"string\"}}}}},\"required\":[\"to\",\"body\"]}}",
	"mail_attach":  "{\"name\":\"mail_attach\",\"group\":\"mail\",\"description\":\"Attach ITSAs and agents to an existing mail, silently: the web UI shows them as chips in its header. It sends no mail, makes no notice and no unread state. Use it instead of replying when all you would say is which ITSA or agent handles a request. Only a recipient of the mail, or the chief of staff, may attach.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"mail_id\":{\"type\":\"string\",\"description\":\"The id of the mail to attach to.\"},\"itsas\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"ITSA keys (S-12) or ids.\"},\"agents\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Agent names or ids.\"}},\"required\":[\"mail_id\"]}}",
	"withdraw_ask": "{\"name\":\"withdraw_ask\",\"group\":\"mail\",\"description\":\"Withdraw your ask from your user when it no longer needs them: answered another way, or moot.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"mail_id\":{\"type\":\"string\",\"description\":\"The id of your decision mail to the human.\"},\"note\":{\"type\":\"string\",\"description\":\"Why, in a few words, for example \\\"answered in the terminal\\\".\"}},\"required\":[\"mail_id\",\"note\"]}}",
	"defer_thread": "{\"name\":\"defer_thread\",\"group\":\"mail\",\"description\":\"Set one of your mail threads aside for later: it leaves your unread count and your list, and comes back when new mail arrives in it. Not archived. Pass undo: true to bring it back now.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"thread_id\":{\"type\":\"string\",\"description\":\"The thread to defer.\"},\"undo\":{\"type\":\"boolean\",\"description\":\"Bring a deferred thread back (default false).\"}},\"required\":[\"thread_id\"]}}",
	"search_mail":  "{\"name\":\"search_mail\",\"group\":\"mail\",\"description\":\"Search mail by keyword: your own mail, and the threads with your user that your parents (and their parents) took part in. Returns one line per thread, best first. Search before you mail your user, to find the thread to answer. \\\"with\\\" limits the results to threads an agent or \\\"human\\\" takes part in. To search ITSAs too, and to match by meaning, use search.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"query\":{\"type\":\"string\",\"description\":\"Words to match in subjects and bodies.\"},\"with\":{\"type\":\"string\",\"description\":\"An agent name or id, or \\\"human\\\": only threads that one takes part in.\"},\"limit\":{\"type\":\"number\",\"description\":\"Threads to return. Defaults to 10, at most 30.\"}},\"required\":[\"query\"]}}",
	"search":       "{\"name\":\"search\",\"group\":\"mail\",\"description\":\"Search by meaning across mail and ITSAs, in one list, best first: the mail search_mail finds (your own, and the threads with your user that your parents took part in) and every ITSA. Each line is tagged [mail] or [itsa]. Words need not match the title: a query worded differently still finds the thread or ITSA about it.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"query\":{\"type\":\"string\",\"description\":\"What to look for, in any words.\"},\"kinds\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"mail\",\"itsa\"]},\"description\":\"What to search: mail, itsa, or both. Defaults to both.\"},\"limit\":{\"type\":\"number\",\"description\":\"Results to return. Defaults to 10, at most 30.\"}},\"required\":[\"query\"]}}",
}
